//! Independent protocol-777 wire fixture. Numeric IDs/fields are checked against the pinned
//! MCProtocolLib codec, not generated by the client state machine under test.
use java_protocol::{
    codec,
    session::{self, Event, Options, Phase},
    stream::Stream,
};
use std::time::Duration;
use tokio::{net::TcpListener, sync::mpsc};
use tokio_util::sync::CancellationToken;
#[path = "session/batch.rs"]
mod batch;
#[path = "session/tags.rs"]
mod tags;

fn text(s: &str, out: &mut Vec<u8>) {
    codec::write_string(s, 32767, out).unwrap();
}
async fn through_configuration(
    listener: TcpListener,
    encrypted: bool,
) -> Stream<tokio::net::TcpStream> {
    let (socket, _) = listener.accept().await.unwrap();
    let mut wire = Stream::new(socket);
    let handshake = wire.read().await.unwrap();
    assert_eq!(&handshake[..3], &[0, 0x89, 0x06]);
    assert_eq!(handshake.last(), Some(&2));
    let start = wire.read().await.unwrap();
    assert_eq!(&start[..9], b"\0\x07Fixture");
    if encrypted {
        use rsa::pkcs8::EncodePublicKey;
        let key = rsa::RsaPrivateKey::new(&mut rand::thread_rng(), 1024).unwrap();
        let public = key.to_public_key().to_public_key_der().unwrap();
        let mut hello = vec![1, 0];
        codec::write_varint(public.as_bytes().len() as i32, &mut hello);
        hello.extend(public.as_bytes());
        hello.extend([4, 1, 2, 3, 4, 0]); // challenge and shouldAuthenticate=false, fixture only.
        wire.write(&hello).await.unwrap();
        let response = wire.read().await.unwrap();
        let mut r = java_protocol::wire::Reader(&response);
        assert_eq!(r.var().unwrap(), 1);
        let secret = key
            .decrypt(rsa::Pkcs1v15Encrypt, &r.bytes(4096).unwrap())
            .unwrap();
        let challenge = key
            .decrypt(rsa::Pkcs1v15Encrypt, &r.bytes(4096).unwrap())
            .unwrap();
        r.finish().unwrap();
        assert_eq!(challenge, [1, 2, 3, 4]);
        wire.encryption(secret.as_slice().try_into().unwrap());
    }
    // Compression is enabled only after this uncompressed packet.
    wire.write(&[3, 0]).await.unwrap();
    wire.compression(0);
    let mut success = vec![2];
    success.extend([0x11; 16]);
    text("Fixture", &mut success);
    success.push(0);
    success.extend([0x22; 16]);
    wire.write(&success).await.unwrap();
    assert_eq!(wire.read().await.unwrap(), [3]); // LoginAcknowledged.
    assert_eq!(
        wire.read().await.unwrap(),
        b"\0\x05en_us\x02\x00\x01\x7f\x01\x00\x00\x00"
    );
    let mut packs = vec![0x0f, 1];
    for s in ["minecraft", "core", "26.3"] {
        text(s, &mut packs);
    }
    wire.write(&packs).await.unwrap();
    assert_eq!(wire.read().await.unwrap(), [7, 0]);
    let mut registry = vec![7];
    text("minecraft:dimension_type", &mut registry);
    registry.push(1);
    text("minecraft:overworld", &mut registry);
    registry.extend([1, 10]);
    for (name, value) in [("min_y", -64i32), ("height", 384i32)] {
        registry.push(3);
        registry.extend((name.len() as u16).to_be_bytes());
        registry.extend(name.bytes());
        registry.extend(value.to_be_bytes());
    }
    registry.push(0);
    wire.write(&registry).await.unwrap();
    let mut biome = vec![7];
    text("minecraft:worldgen/biome", &mut biome);
    biome.push(1);
    text("minecraft:plains", &mut biome);
    biome.extend([1, 10, 0]);
    wire.write(&biome).await.unwrap();
    let mut features = vec![0x0d, 1];
    text("minecraft:vanilla", &mut features);
    wire.write(&features).await.unwrap();
    wire
}

fn world_login() -> Vec<u8> {
    let mut login = vec![0x32];
    login.extend(42i32.to_be_bytes());
    login.extend([0, 1]);
    text("minecraft:overworld", &mut login);
    login.extend([2, 2, 2, 0, 1, 0, 0]);
    text("minecraft:overworld", &mut login);
    login.extend(0i64.to_be_bytes());
    login.extend([0, 255, 0, 1, 0, 0, 63, 0, 0]);
    login
}

async fn through_initial_position(
    listener: TcpListener,
    encrypted: bool,
) -> Stream<tokio::net::TcpStream> {
    let mut wire = through_configuration(listener, encrypted).await;
    wire.write(&[3]).await.unwrap();
    assert_eq!(wire.read().await.unwrap(), [3]);
    wire.write(&world_login()).await.unwrap();
    let mut position = vec![0x49, 7];
    for n in [1f64, 64., 2., 0., 0., 0.] {
        position.extend(n.to_be_bytes());
    }
    position.extend([0; 12]);
    wire.write(&position).await.unwrap();
    wire
}
async fn fixture(listener: TcpListener, done: tokio::sync::oneshot::Sender<()>, encrypted: bool) {
    let mut wire = through_initial_position(listener, encrypted).await;
    let mut acknowledgement = vec![0, 7];
    for coordinate in [1f64, 64., 2.] {
        acknowledgement.extend(coordinate.to_be_bytes());
    }
    acknowledgement.extend([0; 8]);
    assert_eq!(wire.read().await.unwrap(), acknowledgement);
    // Independent official protocol-777 report: player_loaded is 44, with no payload.
    assert_eq!(wire.read().await.unwrap(), [0x2c]);
    // Relative correction arrives after the renderer acknowledgement. Resolved coordinates
    // must come back from the player authority, not be echoed from this delta packet.
    let mut relative = vec![0x49, 7];
    for n in [2f64, -1., 4., 25., 0., 0.] {
        relative.extend(n.to_be_bytes());
    }
    relative.extend(90f32.to_be_bytes());
    relative.extend((-45f32).to_be_bytes());
    relative.extend(0x1ffi32.to_be_bytes());
    wire.write(&relative).await.unwrap();
    let mut resolved = vec![0, 7];
    for n in [3f64, 63., 6.] {
        resolved.extend(n.to_be_bytes());
    }
    resolved.extend(90f32.to_be_bytes());
    resolved.extend((-45f32).to_be_bytes());
    assert_eq!(wire.read().await.unwrap(), resolved);
    // Independent official report: angle-only correction 74, rotation response 32.
    wire.write(&[0x4a, 0x41, 0x20, 0, 0, 1, 0x41, 0xa0, 0, 0, 0])
        .await
        .unwrap();
    assert_eq!(
        wire.read().await.unwrap(),
        [0x20, 0x42, 0xc8, 0, 0, 0x41, 0xa0, 0, 0, 0]
    );
    // Stale prediction is fenced by the correction receipt; only the current batch arrives.
    assert_eq!(wire.read().await.unwrap(), [0x2b, 65]);
    assert_eq!(wire.read().await.unwrap(), [0x2a, 42, 1, 0]);
    assert_eq!(wire.read().await.unwrap(), [0x21, 1]);
    assert_eq!(wire.read().await.unwrap(), [0x0d]);
    // Official report: set_carried_item=54, followed by a signed big-endian short.
    assert_eq!(wire.read().await.unwrap(), [54, 0, 8]);
    // Official protocol-777 report: player_action=41, punch=46, block_changed_ack=4.
    // Retired dimension/correction actions produce no bytes; the current action and punch
    // remain ordered on the same compressed, encrypted stream as movement and receipts.
    assert_eq!(
        wire.read().await.unwrap(),
        [41, 0, 255, 255, 255, 255, 255, 255, 239, 192, 2, 128, 1]
    );
    assert_eq!(wire.read().await.unwrap(), [46]);
    // Official report: use_item_on=66. A held-item block use follows the break on the
    // same encrypted/compressed stream; retired dimension/correction uses emit nothing.
    assert_eq!(
        wire.read().await.unwrap(),
        [
            66, 0, 255, 255, 255, 255, 255, 255, 239, 192, 2, 0x3f, 0, 0, 0, 0x3f, 0x80, 0, 0,
            0x3e, 0x80, 0, 0, 1, 0, 0x81, 1
        ]
    );
    wire.write(&[4, 129, 1]).await.unwrap();
    // Official report: container_set_content=18, set_held_slot=107, set_player_inventory=110.
    // A complete empty player menu precedes a selected slot and a native dirt update.
    let mut inventory = vec![18, 0, 1, 46];
    inventory.extend([0; 47]); // 46 empty slots and an empty cursor.
    wire.write(&inventory).await.unwrap();
    wire.write(&[107, 2]).await.unwrap();
    let mut item = vec![110, 2, 4, 55, 1, 0, 16, 1, 3];
    text("fixture:attack", &mut item);
    item.extend(2.5f64.to_be_bytes());
    item.extend([0, 1, 2, 8, 0, 4, b'B', b'u', b'f', b'f']);
    wire.write(&item).await.unwrap();
    // Abilities and the new packed velocity are delivered as admitted schemas, not deferred bytes.
    wire.write(&[0x41, 0, 0x3d, 0x4c, 0xcc, 0xcd, 0x3d, 0xcc, 0xcc, 0xcd])
        .await
        .unwrap();
    wire.write(&[0x67, 42, 0xf1, 0xff, 0, 0, 0xff, 0xff])
        .await
        .unwrap();
    // Official protocol-777 report: add_entity=1, move_entity_pos=54, remove_entities=78.
    // The encrypted/compressed stream must preserve lifecycle order into the bounded queue.
    let mut spawn = vec![1, 99];
    spawn.extend([0x33; 16]);
    spawn.push(101); // minecraft:pig, independently checked against the official registry report.
    for n in [1f64, 64., 2.] {
        spawn.extend(n.to_be_bytes());
    }
    spawn.extend([0, 0, 0, 0, 0]); // zero LpVec3, angles and object data.
    wire.write(&spawn).await.unwrap();
    wire.write(&[101, 99, 16, 8, 1, 255]).await.unwrap(); // Native baby metadata.
    wire.write(&[54, 99, 1, 0x10, 0, 0, 0, 0, 0]).await.unwrap();
    wire.write(&[78, 1, 99]).await.unwrap();
    // Independent official report IDs: set_experience=105, game_event=39.
    wire.write(&[105, 0x3f, 0, 0, 0, 12, 0xac, 2])
        .await
        .unwrap();
    wire.write(&[39, 3, 0x40, 0, 0, 0]).await.unwrap();
    // Official protocol-777 report: death 69, client command 12, respawn 84.
    wire.write(&[0x45, 42, 8, 0, 4, b't', b'e', b's', b't'])
        .await
        .unwrap();
    assert_eq!(wire.read().await.unwrap(), [0x0c, 0]);
    let mut respawn = vec![0x54, 0];
    text("minecraft:overworld", &mut respawn);
    respawn.extend(0i64.to_be_bytes());
    respawn.extend([0, 255, 0, 1, 0, 0, 63, 0]);
    wire.write(&respawn).await.unwrap();
    assert_eq!(wire.read().await.unwrap(), [0x2c]);
    for token in [123i64, 456] {
        let mut keep = vec![0x2d];
        keep.extend(token.to_be_bytes());
        wire.write(&keep).await.unwrap();
        let mut expected = vec![0x1c];
        expected.extend(token.to_be_bytes());
        assert_eq!(wire.read().await.unwrap(), expected);
    }
    let _ = done.send(());
    // Client cancellation closes the transport, rather than leaving an orphaned reader.
    assert!(wire.read().await.is_err());
}
#[tokio::test]
async fn login_configuration_play_keepalives_and_cancellation() {
    let listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
    let address = listener.local_addr().unwrap().to_string().parse().unwrap();
    let (done, complete) = tokio::sync::oneshot::channel();
    let server = tokio::spawn(fixture(listener, done, true));
    let (tx, mut rx) = mpsc::channel(32);
    let cancel = CancellationToken::new();
    let child = cancel.clone();
    let (commands, input) = mpsc::channel(2);
    let mut options = Options::fixture(address, "Fixture".into(), 7);
    options.commands = Some(input);
    let client = tokio::spawn(session::run(options, tx, child));
    let mut phases = Vec::new();
    let mut bootstrap = false;
    let mut position = false;
    let mut keepalives = 0;
    let mut dynamics = 0;
    let mut rotation = false;
    let mut entities = Vec::new();
    let mut hud = Vec::new();
    let mut block_receipts = Vec::new();
    let mut inventory = Vec::new();
    tokio::time::timeout(Duration::from_secs(10), async {
        while let Some(envelope) = rx.recv().await {
            assert_eq!(envelope.generation, 7);
            match envelope.event {
                Event::SelectionSent {
                    dimension_epoch,
                    sequence,
                    slot,
                } => {
                    assert_eq!((dimension_epoch, sequence, slot), (1, 1, 8));
                    inventory.push("local selection");
                }
                Event::Inventory {
                    dimension_epoch,
                    packet,
                } => {
                    assert_eq!(dimension_epoch, 1);
                    match packet {
                        session::inventory::Packet::Content {
                            container,
                            state,
                            slots,
                            carried,
                        } => {
                            assert_eq!((container, state), (0, 1));
                            assert_eq!(slots.len(), 46);
                            assert!(slots.iter().all(Option::is_none) && carried.is_none());
                            inventory.push("content");
                        }
                        session::inventory::Packet::Selected(slot) => {
                            assert_eq!(slot, 2);
                            inventory.push("selected");
                        }
                        session::inventory::Packet::PlayerSlot { slot, stack } => {
                            assert_eq!(slot, 2);
                            let stack = stack.unwrap();
                            assert_eq!((stack.item, stack.count), (55, 4));
                            let modifier =
                                &stack.added["minecraft:attribute_modifiers"]["modifiers"][0];
                            assert_eq!(modifier["attribute"], "minecraft:attack_damage");
                            assert_eq!(modifier["modifier"]["amount"], 2.5);
                            assert_eq!(modifier["slot"], "main_hand");
                            assert_eq!(modifier["display"]["type"], "override");
                            inventory.push("slot");
                        }
                        _ => panic!("unexpected inventory packet"),
                    }
                }
                Event::BlockAck {
                    dimension_epoch,
                    sequence,
                } => {
                    block_receipts.push((dimension_epoch, sequence));
                }
                Event::Hud(session::hud::Packet::Experience {
                    progress,
                    level,
                    total,
                }) => {
                    assert_eq!((progress, level, total), (0.5, 12, 300));
                    hud.push("experience");
                }
                Event::Hud(session::hud::Packet::GameMode(mode)) => {
                    assert_eq!(mode, session::hud::GameMode::Adventure);
                    hud.push("mode");
                }
                Event::Phase(p) => phases.push(p),
                Event::Bootstrap(b) => {
                    assert_eq!(b.world.entity_id, 42);
                    assert_eq!(b.server_session, uuid::Uuid::from_bytes([0x22; 16]));
                    bootstrap = true
                }
                Event::Teleport {
                    dimension_epoch,
                    sequence,
                    correction: p,
                } => {
                    assert_eq!(dimension_epoch, 1);
                    if sequence == 2 {
                        assert_eq!(p.id, 7);
                        commands
                            .send(session::Command::AcceptTeleport {
                                dimension_epoch,
                                sequence: 1,
                                id: 7,
                                position: [1., 64., 2.],
                                yaw: 0.,
                                pitch: 0.,
                            })
                            .await
                            .unwrap();
                        assert_eq!(p.position, [2., -1., 4.]);
                        assert_eq!(p.relative, 0x1ff);
                        commands
                            .send(session::Command::AcceptTeleport {
                                dimension_epoch,
                                sequence,
                                id: p.id,
                                position: [3., 63., 6.],
                                yaw: 90.,
                                pitch: -45.,
                            })
                            .await
                            .unwrap();
                        continue;
                    }
                    assert_eq!(p.position, [1., 64., 2.]);
                    position = true;
                    // Retired epoch, wrong id, then the admitted pose. Only the last is sent.
                    for (epoch, id) in [(99, 7), (1, 99), (1, 7)] {
                        commands
                            .send(session::Command::AcceptTeleport {
                                dimension_epoch: epoch,
                                sequence,
                                id,
                                position: p.position,
                                yaw: p.yaw,
                                pitch: p.pitch,
                            })
                            .await
                            .unwrap();
                    }
                    for epoch in [99, 1, 1] {
                        commands
                            .send(session::Command::PlayerLoaded {
                                dimension_epoch: epoch,
                            })
                            .await
                            .unwrap();
                    }
                }
                Event::Rotation {
                    dimension_epoch,
                    sequence,
                    yaw,
                    relative_yaw,
                    pitch,
                    relative_pitch,
                } => {
                    assert_eq!(
                        (yaw, relative_yaw, pitch, relative_pitch),
                        (10., true, 20., false)
                    );
                    assert_eq!(sequence, 3);
                    for (epoch, receipt) in [
                        (99, sequence),
                        (dimension_epoch, 2),
                        (dimension_epoch, sequence),
                    ] {
                        commands
                            .send(session::Command::AcceptRotation {
                                dimension_epoch: epoch,
                                sequence: receipt,
                                yaw: 100.,
                                pitch: 20.,
                            })
                            .await
                            .unwrap();
                    }
                    rotation = true;
                    for sequence in [2, 3] {
                        commands
                            .send(session::Command::Move {
                                dimension_epoch,
                                sequence,
                                frame: session::movement::Frame {
                                    entity: 42,
                                    position: None,
                                    rotation: None,
                                    on_ground: true,
                                    horizontal_collision: false,
                                    input: Some(65),
                                    sprinting: Some(true),
                                },
                            })
                            .await
                            .unwrap();
                    }
                    for epoch in [99, dimension_epoch] {
                        commands
                            .send(session::Command::Select {
                                dimension_epoch: epoch,
                                sequence: 1,
                                slot: 8,
                            })
                            .await
                            .unwrap();
                    }
                    for (epoch, correction) in [(99, 3), (dimension_epoch, 2), (dimension_epoch, 3)]
                    {
                        commands
                            .send(session::Command::Interact {
                                dimension_epoch: epoch,
                                correction_sequence: correction,
                                action: session::interaction::Dig {
                                    action: session::interaction::Action::Start,
                                    position: [-1, -64, -2],
                                    face: session::interaction::Face::North,
                                    sequence: 128,
                                },
                            })
                            .await
                            .unwrap();
                    }
                    for (epoch, correction) in [(99, 3), (dimension_epoch, 2), (dimension_epoch, 3)]
                    {
                        commands
                            .send(session::Command::UseOn {
                                dimension_epoch: epoch,
                                correction_sequence: correction,
                                action: session::interaction::UseOn {
                                    hand: session::interaction::Hand::Main,
                                    position: [-1, -64, -2],
                                    face: session::interaction::Face::North,
                                    cursor: [0.5, 1., 0.25],
                                    inside: true,
                                    world_border: false,
                                    sequence: 129,
                                },
                            })
                            .await
                            .unwrap();
                    }
                }
                Event::Dynamics {
                    dimension_epoch,
                    packet,
                } => {
                    assert_eq!(dimension_epoch, 1);
                    match packet {
                        session::dynamics::Packet::Abilities(a) => {
                            assert!(!a.flying && !a.creative)
                        }
                        session::dynamics::Packet::Velocity { entity, velocity } => {
                            assert_eq!(entity, 42);
                            assert_eq!(velocity, [1., 0., -1.]);
                        }
                        _ => panic!("unexpected dynamics"),
                    }
                    dynamics += 1;
                }
                Event::Entities {
                    dimension_epoch,
                    packet,
                } => {
                    use session::entities::{Delta, Packet};
                    assert_eq!(dimension_epoch, 1);
                    match packet {
                        Packet::Spawn(s) => {
                            assert_eq!((s.id, s.kind, s.uuid), (99, "minecraft:pig", [0x33; 16]));
                            assert_eq!(s.position, [1., 64., 2.]);
                            entities.push("spawn");
                        }
                        Packet::Metadata(p) => {
                            assert_eq!(p.id, 99);
                            assert!(p.unsupported.is_none());
                            assert_eq!(p.entries.len(), 1);
                            assert_eq!(
                                p.entries[0].value,
                                session::entities::metadata::Value::Bool(true)
                            );
                            entities.push("metadata");
                        }
                        Packet::Move {
                            id,
                            delta,
                            on_ground,
                            ..
                        } => {
                            assert_eq!(id, 99);
                            assert_eq!(delta, Delta::Linear([4096, 0, 0]));
                            assert!(on_ground);
                            entities.push("move");
                        }
                        Packet::Remove(ids) => {
                            assert_eq!(ids, [99]);
                            entities.push("remove");
                        }
                        _ => panic!("unexpected entity fixture"),
                    }
                }
                Event::Death { player_id, message } => {
                    assert_eq!(player_id, 42);
                    assert_eq!(message, java_protocol::nbt::Value::String("test".into()));
                    commands.send(session::Command::Respawn).await.unwrap();
                }
                Event::Respawn {
                    keep_attribute_modifiers,
                    keep_metadata,
                    ..
                } => {
                    assert!(!keep_attribute_modifiers && !keep_metadata);
                    for epoch in [1, 2, 2] {
                        commands
                            .send(session::Command::PlayerLoaded {
                                dimension_epoch: epoch,
                            })
                            .await
                            .unwrap();
                    }
                }
                Event::KeepAlive(_) => {
                    keepalives += 1;
                    if keepalives == 2 {
                        break;
                    }
                }
                _ => {}
            }
        }
        complete.await.unwrap();
        cancel.cancel();
        assert!(matches!(
            client.await.unwrap(),
            Err(session::Error::Cancelled)
        ));
        server.await.unwrap();
    })
    .await
    .unwrap();
    assert_eq!(
        phases,
        [
            Phase::Connecting,
            Phase::Login,
            Phase::Configuration,
            Phase::Play
        ]
    );
    assert!(bootstrap && position);
    assert_eq!(keepalives, 2);
    assert!(rotation);
    assert_eq!(dynamics, 2);
    assert_eq!(entities, ["spawn", "metadata", "move", "remove"]);
    assert_eq!(hud, ["experience", "mode"]);
    assert_eq!(block_receipts, [(1, 129)]);
    assert_eq!(
        inventory,
        ["local selection", "content", "selected", "slot"]
    );
}
#[tokio::test]
async fn wrong_state_packet_fails_without_play() {
    let listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
    let address = listener.local_addr().unwrap().to_string().parse().unwrap();
    let server = tokio::spawn(async move {
        let (socket, _) = listener.accept().await.unwrap();
        let mut s = Stream::new(socket);
        s.read().await.unwrap();
        s.read().await.unwrap();
        s.write(&[0x2d, 0]).await.unwrap();
    });
    let (tx, _rx) = mpsc::channel(32);
    let result = session::run(
        Options::fixture(address, "Fixture".into(), 1),
        tx,
        CancellationToken::new(),
    )
    .await;
    assert!(matches!(result, Err(session::Error::Protocol(_))));
    server.await.unwrap();
}

#[tokio::test]
async fn unapplied_correction_times_out_and_cancellation_closes_waiting_transport() {
    for cancelled in [false, true] {
        let listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
        let address = listener.local_addr().unwrap().to_string().parse().unwrap();
        let server = tokio::spawn(async move {
            let mut wire = through_initial_position(listener, false).await;
            assert!(
                wire.read().await.is_err(),
                "no acknowledgement before domain admission"
            );
        });
        let (tx, mut rx) = mpsc::channel(32);
        let (_commands, input) = mpsc::channel(2);
        let cancel = CancellationToken::new();
        let mut options = Options::fixture(address, "Fixture".into(), 7);
        options.commands = Some(input);
        let client = tokio::spawn(session::run(options, tx, cancel.clone()));
        tokio::time::timeout(Duration::from_secs(10), async {
            loop {
                if matches!(rx.recv().await.unwrap().event, Event::Teleport { .. }) {
                    break;
                }
            }
        })
        .await
        .unwrap();
        if cancelled {
            cancel.cancel();
            assert!(matches!(
                client.await.unwrap(),
                Err(session::Error::Cancelled)
            ));
        } else {
            tokio::time::pause();
            tokio::time::advance(Duration::from_secs(11)).await;
            assert!(matches!(
                client.await.unwrap(),
                Err(session::Error::TeleportAdmissionTimeout)
            ));
            tokio::time::resume();
        }
        server.await.unwrap();
    }
}
